def is_palindrome(s):
    cleaned = ''.join(c.lower() for c in s if c.isalnum())
    return cleaned == cleaned[::-1]

def binary_search(arr, target):
    left, right = 0, len(arr)-1
    while left <= right:
        mid = (left+right)//2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid+1
        else:
            right = mid-1
    return -1

def merge_sorted(arr1, arr2):
    i=j=0
    res=[]
    while i<len(arr1) and j<len(arr2):
        if arr1[i] < arr2[j]:
            res.append(arr1[i]); i+=1
        else:
            res.append(arr2[j]); j+=1
    res.extend(arr1[i:]); res.extend(arr2[j:])
    return res

def fib(n):
    if n < 2: return n
    a,b = 0,1
    for _ in range(2,n+1):
        a,b = b, a+b
    return b
